+        width: 1.35rem;
+        height: 1.35rem;
+        margin: 0.08rem 0 0;
+        accent-color: var(--accent);
+        cursor: pointer;
+      }
+
+      label {
+        font-weight: 760;
+        line-height: 1.45;
+        cursor: pointer;
+      }
+
+      .required-note {
+        font-weight: 700;
+      }
+
+      .helper,
+      .error,
+      .status {
+        margin: 0;
+        font-size: 0.92rem;
+        line-height: 1.45;
+      }
+
