    <style>
      :root {
        color-scheme: light;
        --bg: #f6f8fb;
        --card: #ffffff;
        --text: #111827;
        --muted: #5b6472;
        --border: #d8dee8;
        --accent: #3158e7;
        --accent-strong: #2446bd;
        --danger: #b42318;
        --success: #147a3d;
        --ring: #8ea2ff;
        --shadow: 0 24px 70px rgb(17 24 39 / 14%);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgb(49 88 231 / 18%), transparent 32rem),
          linear-gradient(135deg, #f9fbff 0%, var(--bg) 46%, #eef3ff 100%);
