      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target),
    })),
  };
  console.log(JSON.stringify(summary, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
