const { chromium } = require('playwright');
const axe = require('axe-core');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  await page.goto(`file://${path.resolve('index.html')}`, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run(document, {
    resultTypes: ['violations'],
  }));
  await browser.close();

  const wcag = results.violations.filter((violation) => !violation.tags.includes('best-practice'));
  const bp = results.violations.filter((violation) => violation.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target),
    })),
    bp: bp.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target),
    })),
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
