 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Terms Consent</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f6f8fb;
         --card: #ffffff;
         --text: #111827;
         --muted: #5b6472;
         --border: #d8dee8;
         --accent: #3158e7;
         --accent-strong: #2446bd;
         --danger: #b42318;
         --success: #147a3d;
         --ring: #2446bd;
         --shadow: 0 24px 70px rgb(17 24 39 / 14%);
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgb(49 88 231 / 18%), transparent 32rem),
           linear-gradient(135deg, #f9fbff 0%, var(--bg) 46%, #eef3ff 100%);
       }

       a {
         color: inherit;
       }

       a:focus-visible,
       button:focus-visible,
       input:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 3px;
       }

       .skip-link {
         position: absolute;
         top: 1rem;
         left: 1rem;
         z-index: 10;
         transform: translateY(-150%);
         border-radius: 999px;
         padding: 0.65rem 1rem;
         color: #ffffff;
         background: var(--text);
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 30rem);
         border: 1px solid rgb(216 222 232 / 80%);
         border-radius: 1.5rem;
         padding: clamp(1.5rem, 5vw, 2.5rem);
         background: rgb(255 255 255 / 88%);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .eyebrow {
         margin: 0 0 0.75rem;
         color: var(--accent-strong);
         font-size: 0.78rem;
         font-weight: 800;
         letter-spacing: 0.12em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 8vw, 3rem);
         line-height: 1;
         letter-spacing: -0.05em;
       }

       .intro {
         margin: 1rem 0 2rem;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         display: grid;
         gap: 0.65rem;
         border: 1px solid var(--border);
         border-radius: 1rem;
         padding: 1rem;
         background: #fbfcff;
       }

       .checkbox-row {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.75rem;
         align-items: start;
       }

       input[type="checkbox"] {
         width: 1.35rem;
         height: 1.35rem;
         margin: 0.08rem 0 0;
         accent-color: var(--accent);
         cursor: pointer;
       }

       label {
         font-weight: 760;
         line-height: 1.45;
         cursor: pointer;
       }

       .required-note {
         font-weight: 700;
       }

       .helper,
       .error,
       .status {
         margin: 0;
         font-size: 0.92rem;
         line-height: 1.45;
       }

       .helper {
         color: var(--muted);
         padding-left: 2.1rem;
       }

       .error {
         color: var(--danger);
         font-weight: 700;
         padding-left: 2.1rem;
       }

       [hidden] {
         display: none !important;
       }

       button {
         min-height: 3rem;
         border: 0;
         border-radius: 999px;
         padding: 0.85rem 1.25rem;
         color: #ffffff;
         background: var(--accent);
         box-shadow: 0 12px 28px rgb(49 88 231 / 25%);
         font: inherit;
         font-weight: 800;
         cursor: pointer;
         transition:
           background-color 160ms ease,
           transform 160ms ease,
           box-shadow 160ms ease;
       }

       button:hover {
         background: var(--accent-strong);
         box-shadow: 0 14px 32px rgb(49 88 231 / 32%);
         transform: translateY(-1px);
       }

       button:active {
         transform: translateY(0);
       }

       .status {
         min-height: 1.35rem;
         color: var(--success);
         font-weight: 700;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .form-field,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>

     <main id="main">
       <section class="card" aria-labelledby="page-title">
         <p class="eyebrow">Account setup</p>
         <h1 id="page-title">Review and continue</h1>
         <p class="intro">
           Confirm your consent to continue using the product experience.
         </p>

         <form id="consent-form" novalidate>
           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="terms-consent"
                 name="termsConsent"
                 type="checkbox"
                 required
                 aria-describedby="terms-help terms-error"
               >
               <label for="terms-consent">
                 I agree to the terms of use
                 <span class="required-note">(required)</span>
               </label>
             </div>
             <p id="terms-help" class="helper">
               You must agree before continuing.
             </p>
             <p id="terms-error" class="error" hidden>
               Error: Agree to the terms of use to continue.
             </p>
           </div>

           <button type="submit">Continue</button>
           <p id="form-status" class="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#consent-form");
       const checkbox = document.querySelector("#terms-consent");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       function clearError() {
         checkbox.removeAttribute("aria-invalid");
         error.hidden = true;
       }

       function showError() {
         checkbox.setAttribute("aria-invalid", "true");
         error.hidden = false;
         status.textContent = "";
         checkbox.focus();
       }

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           clearError();
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           showError();
           return;
         }

         clearError();
         status.textContent = "Consent saved. You can continue.";
       });
     </script>
   </body>
 </html>

